#!/bin/bash
set -euo pipefail
r=.cache/tasks/rc-freeze-publication
e=evidence/research/rc-freeze-publication
bash "$r/assert.sh" > "$r/assertions.log" 2>&1
rg -q '13 passing' "$r/freeze-tests.log"
rg -q '9 passing' "$r/generation-tests.log"
for p in rc_freeze_publication generational_root_admission; do rg -q 'No violation found' "$r/$p-simulation.log"; done
! rg -q 'error:|sorryAx' "$r/freeze-lean.log" "$r/generation-lean.log" "$r/lean-scopes.log"
jq -e '.missingFiles==[] and .missingCustomIds==[] and .duplicateIds==[]' "$r/org-links.json" >/dev/null
jq -e '.exit==0 and ((.errors//[])|length)==0' "$r/native-metadata.json" >/dev/null
rg --files dev -g '*.sysml' -0 | xargs -0 openssl dgst -sha256 | LC_ALL=C sort > "$r/models-after.sha256"
cmp "$r/models-before.sha256" "$r/models-after.sha256"
sed -E 's/^[^(]+\((.*)\)= .*/\1/' "$r/entry-sources.sha256" | while IFS= read -r f; do openssl dgst -sha256 "$f"; done > "$r/preserved-after.sha256"
cmp "$r/entry-sources.sha256" "$r/preserved-after.sha256"
jq -r 'to_entries[]|[.key,.value]|@tsv' "$r/source-bindings.json" | while IFS=$'\t' read -r f expected; do test "$(openssl dgst -sha256 "$f"|awk '{print $NF}')" = "$expected"; done
jq -Rn '[inputs|capture("^[^(]+\\((?<key>.+)\\)= (?<value>[a-f0-9]{64})$")]|from_entries' "$r/models-after.sha256" > "$r/model-bindings.json"
jq --slurpfile m "$r/model-bindings.json" '.modelSourceBindings += $m[0]' dev/modeling/formal-bindings.json > "$r/formal-bindings-next.json"
cp "$r/formal-bindings-next.json" dev/modeling/formal-bindings.json
jq -e --slurpfile old "$r/entry-formal-bindings.json" 'del(.modelSourceBindings)==($old[0]|del(.modelSourceBindings))' dev/modeling/formal-bindings.json >/dev/null
jq -n --slurpfile p "$r/planner-input.json" --slurpfile a "$r/case-current.json" '[$p[0].components[]|.id as $id|{component:$id,needs:([$p[0].needs[]|select(.component==$id)]|length),qualifiedLocal:([$a[0].locallyChecked[]|select(.[1]==$id)]|length),frontier:[$a[0].componentFrontier[]|select(.[1]==$id)|.[2]],complete:([$a[0].componentReady[]|select(.[1]==$id)]|length>0)}]' > "$r/closure-matrix.json"
for s in $(jq -r '.cases[].id' "$r/scenarios.json"); do jq --arg case "$s" '{case:$case,componentReady:(.componentReady|map(.[1])|sort),qualifiedLocal:(.locallyChecked|length),frontier:(.componentFrontier|length),sourceRoutes:(.sourceRoute|length),runtimeAdmitted}' "$r/case-$s.json"; done | jq -s . > "$r/scenario-summary.json"
jq -n --slurpfile p "$r/planner-input.json" --slurpfile b "$r/source-bindings.json" '{qnt:[{source:"models/gambit/rc_freeze_publication.qnt",histories:13,testsLog:"freeze-tests.log",typecheckLog:"freeze-typecheck-final.log",simulationLog:"rc_freeze_publication-simulation.log"},{source:"models/gambit/generational_root_admission.qnt",histories:9,testsLog:"generation-tests.log",typecheckLog:"generation-typecheck-final.log",simulationLog:"generational_root_admission-simulation.log"}]|map(.+{sourceSha256:$b[0][.source],seed:17,samplesPerHistory:1,positiveSamples:100,maxSteps:50,invariant:"safe",exhaustive:false}),lean:[{source:"models/gambit/lean/RcFreezePublication.lean",namedStatements:7,log:"freeze-lean.log"},{source:"models/gambit/lean/GenerationalRootAdmission.lean",namedStatements:5,log:"generation-lean.log"}]|map(.+{sourceSha256:$b[0][.source]}),scopeProbe:{source:"probe.lean",log:"lean-scopes.log",namedStatements:12},exactScopes:[$p[0].needs[]|select(.obligationId=="FZ-H" or .obligationId=="FZ-I" or .obligationId=="GEN-H" or .obligationId=="GEN-I")|{component,obligationId,subjectPath,subjectScope,digest}],wholeCollectorProof:false,productModelExecuted:false,cSourceSimulation:false,nativeRuntimeTest:false,livenessProved:false}' > "$r/formal-checks.json"
jq -n '{readPrimary:[{url:"https://cisco.github.io/ChezScheme/csug10.0/smgmt.html",scope:"section 13.1 generation policy"},{url:"https://anil.recoil.org/papers/2020-icfp-retropar.pdf",scope:"sections 4.3-4.4 and 5.4; C interface tradeoff"},{url:"https://mailman.iro.umontreal.ca/pipermail/gambit-list/2019-November/009234.html",scope:"Historical author statement; not current binary qualification"},{url:"https://www.iro.umontreal.ca/~feeley/papers/FeeleyMillerLFP90.pdf",scope:"PVM semantic/native separation; no current generational proof"},{url:"https://simonmar.github.io/bib/papers/parallel-gc.pdf",scope:"sections 3-4; no benchmark transfer"}],unavailable:[{url:"https://www.iro.umontreal.ca/~feeley/papers/ismm98.pdf",result:"access denied; no paper-content claim from snippet"},{url:"https://raw.githubusercontent.com/tcltk/tcl/cbf86d62348d6b052e1961b4df995960fb21545f/generic/tclBasic.c",result:"cache miss; current pinned external callback/failure semantics unresolved"}],sourceCensus:{primitiveLexicalOccurrences:116,files:9,semanticFamilies:8,nativeCensusRoutes:7,externalClosureProved:false},boundary:"Web reading and source hashes do not qualify a loaded host runtime"}' > "$r/primary-evidence.json"
quint --version > "$r/quint-version.txt"
sysml --version > "$r/sysml-version.txt" 2>&1
d2 --version > "$r/d2-version.txt" 2>&1
lean --version > "$r/lean-version.txt" 2>&1
# Only research records. No runtime binaries, runtime native tests or olean artifacts.
rg --files --hidden --no-ignore "$r" -g '*.json' -g '*.ss' -g '*.scm' -g '*.log' -g '*.sh' -g '*.el' -g '*.jq' -g '*.sha256' -g '*.txt' -g '*.tsv' -g 'probe.lean' -g '*.png' | while IFS= read -r f; do cp "$f" "$e/$(basename "$f")"; done
jq -n --slurpfile p "$r/planner-input.json" --slurpfile a "$r/case-current.json" --slurpfile f "$r/formal-checks.json" --slurpfile s "$r/scenario-summary.json" --slurpfile c "$r/closure-matrix.json" --slurpfile h "$r/source-bindings.json" --slurpfile o "$r/org-links.json" --slurpfile v "$r/native-values.json" --arg head "$(git rev-parse HEAD)" --arg time "$(date -u +%FT%TZ)" '{kind:"modern-c-generational-and-native-freeze-design",status:"coherent-runtime-redesign-local-kernels-checked-source-open",recordedAt:$time,repositoryHead:$head,authority:{policy:"dev/modeling/models/sysml/assurance-routing.sysml",nativeFreeze:"dev/architecture/runtime/ffi/models/sysml/rc-freeze-publication.sysml",generational:"dev/architecture/runtime/gc/models/sysml/generational-admission.sysml",inference:"dev/modeling/ascent/assurance-planner.ss"},inputIdentity:{modelBundleSha256:$p[0].bundleHash,nativeOutputSha256:$p[0].nativeHash,dslSha256:$p[0].dslHash},sourceBindings:$h[0],structure:{nativeSysmlFiles:42,nativeEvaluatedScalars:($v[0]|length),components:8,needs:59,directPrerequisites:130,sharedContracts:8,sourceRoutes:19,nativeMetadataAuthority:true,satisfactionClaimed:false},closure:{currentQualifiedLocalSlices:24,inheritedUnchangedSlices:20,currentSourceSimulationOpen:25,currentPlatformOpen:10,currentCompleteComponents:0,legacyGlobalObligationLedgerReclassified:false},formal:$f[0],reasoning:{current:$a[0],scenarios:$s[0],scenarioCases:13,selectedHypotheses:1,retainedTaskHypotheses:$a[0].retainedTaskHypotheses,supportObservations:0,exactRequiredRowsChecked:59,exactSourceRoutesChecked:19,allNativeDirectEdgesRetained:130,parserLimitsRaised:false},componentClosure:$c[0],org:{missingFiles:$o[0].missingFiles,missingCustomIds:$o[0].missingCustomIds,duplicateIds:$o[0].duplicateIds,babelExecuted:false},predecessor:{receipt:"evidence/research/retained-rc-scan/checks.json",sha256:"8ccb54a232bd141dc83ec4fc6e314a1ad62cdd59f8e6a3f012001973b0ac6734",rerun:false,sourceDigestAndScopeChecked:true},views:{generational:{nodes:10,edges:12,visuallyReviewed:true},freeze:{nodes:14,edges:30,visuallyReviewed:true},composed:{nodes:59,edges:130,topologyChecked:true}},execution:{sysmlNativeValidation:true,quintHistoryChecks:true,quintPositiveSimulation:true,leanKernelChecks:true,ascentQueries:true,runtimeImplementation:false,nativeRuntimeTesting:false,performanceValidation:false,commitOrPush:false},benefit:{kind:"conditional-work-and-memory-equation",nativeSpeedupMeasured:false,personDaysUsed:false,modernCMandatory:true,zigIncrementalBenefitEstablished:false}}' > "$e/checks.json"
